import React from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Building2, MapPin, Calendar, DollarSign, ChevronLeft, Send } from 'lucide-react';

const OpportunityDetailPage = ({ id, isModal }) => {
  const navigate = useNavigate();
  
  // إذا لم يأتِ id كـ prop (حالة الصفحة المنفصلة)، نأخذه من الـ URL
  const { id: urlId } = useParams();
  const currentId = id || urlId;

  const handleApply = () => {
    alert("Application sent successfully to the company!");
    // التوجه لصفحة طلباتي بعد التقديم
    navigate('/myapplication'); 
  };

  return (
    <div style={{ padding: '20px', maxWidth: '900px', margin: '0 auto' }}>
      {/* زر العودة يظهر فقط إذا لم نكن داخل المودال */}
      {!isModal && (
        <button 
          onClick={() => navigate('/opportunities')}
          style={{ display: 'flex', alignItems: 'center', gap: '5px', border: 'none', background: 'none', cursor: 'pointer', marginBottom: '20px', color: '#6b21a8' }}
        >
          <ChevronLeft size={20} /> Back to Opportunities
        </button>
      )}

      <div style={{ backgroundColor: 'white', borderRadius: '20px', overflow: 'hidden' }}>
        {/* Header Section */}
        <div style={{ padding: '30px', borderBottom: '1px solid #eee', display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
          <div style={{ display: 'flex', gap: '20px', alignItems: 'center' }}>
            <div style={{ backgroundColor: '#f3e8ff', padding: '15px', borderRadius: '15px' }}>
              <Building2 size={32} color="#7e22ce" />
            </div>
            <div>
              <h2 style={{ fontSize: '24px', fontWeight: 'bold', color: '#1f2937', margin: 0 }}>
                Frontend Development Internship
              </h2>
              <p style={{ color: '#6b7280', marginTop: '5px' }}>Tech Solutions Inc. #{currentId}</p>
            </div>
          </div>
          <button 
            onClick={handleApply}
            style={{ backgroundColor: '#4a3f6b', color: 'white', padding: '12px 25px', borderRadius: '12px', border: 'none', fontWeight: 'bold', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '8px' }}
          >
            <Send size={18} /> Apply Now
          </button>
        </div>

        {/* Content Section */}
        <div style={{ padding: '30px' }}>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '20px', marginBottom: '30px' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '10px', color: '#4b5563' }}>
              <MapPin size={20} color="#c5a3d1" /> Constantine, Algeria
            </div>
            <div style={{ display: 'flex', alignItems: 'center', gap: '10px', color: '#4b5563' }}>
              <Calendar size={20} color="#c5a3d1" /> 3 Months
            </div>
            <div style={{ display: 'flex', alignItems: 'center', gap: '10px', color: '#4b5563' }}>
              <DollarSign size={20} color="#c5a3d1" /> Paid Internship
            </div>
          </div>

          <div style={{ marginBottom: '30px' }}>
            <h3 style={{ fontSize: '18px', fontWeight: 'bold', color: '#1f2937', marginBottom: '15px' }}>About the Internship</h3>
            <p style={{ color: '#4b5563', lineHeight: '1.6' }}>
              We are looking for a passionate Frontend Developer intern to join our dynamic team. 
              You will work on building modern web interfaces using React.js and Tailwind CSS.
            </p>
          </div>

          <div>
            <h3 style={{ fontSize: '18px', fontWeight: 'bold', color: '#1f2937', marginBottom: '15px' }}>Requirements</h3>
            <ul style={{ color: '#4b5563', lineHeight: '1.8', paddingLeft: '20px' }}>
              <li>Currently studying Computer Science or related field (L3 or Master).</li>
              <li>Basic knowledge of JavaScript (ES6+), HTML, and CSS.</li>
              <li>Familiarity with React.js is a plus.</li>
            </ul>
          </div>
        </div>
      </div>
    </div>
  );
};
